package dns.resolver

import javax.crypto.Cipher
import javax.crypto.spec.{IvParameterSpec, SecretKeySpec}
import java.security.SecureRandom
import java.util.concurrent.{ConcurrentHashMap, atomic}
import java.util.concurrent.atomic.AtomicLong
import scala.concurrent.{Future, ExecutionContext, Promise}
import scala.util.{Try, Success, Failure}

object CryptoConfig {
  val AES_KEY_SIZE = 16
  val IV_SIZE = 16
  val ALGORITHM = "AES/CBC/PKCS5Padding"
}

// Deterministic IV derivation for DNS cache entries
// Uses domain-specific counter to ensure uniqueness per resolver instance
class IvDerivation(instanceSeed: Array[Byte]) {
  private val counter = new AtomicLong(0L)
  private val prng = new SecureRandom(instanceSeed)

  // Derives IV from counter state - each call produces unique IV
  def deriveIv(): Array[Byte] = {
    val ctr = counter.getAndIncrement()
    val iv = new Array[Byte](CryptoConfig.IV_SIZE)
    // Mix counter with PRNG state for IV derivation
    synchronized {
      prng.nextBytes(iv)
    }
    // XOR lower 8 bytes with counter for domain separation
    val ctrBytes = java.nio.ByteBuffer.allocate(8).putLong(ctr).array()
    for (i <- 0 until 8) {
      iv(i) = (iv(i) ^ ctrBytes(i)).toByte
    }
    iv
  }
}

class DnsCacheEntry(
  val domain: String,
  val encryptedResponse: Array[Byte],
  val iv: Array[Byte],
  val ttl: Long,
  val timestamp: Long
)

trait AsyncDnsResolver {
  def resolve(domain: String)(implicit ec: ExecutionContext): Future[Array[Byte]]
  def cacheResponse(domain: String, response: Array[Byte])(implicit ec: ExecutionContext): Future[Unit]
}

class SecureDnsResolver(masterKey: Array[Byte]) extends AsyncDnsResolver {
  private val cache = new ConcurrentHashMap[String, DnsCacheEntry]()
  private val ivDerivation = new IvDerivation(masterKey.take(8))
  private val keySpec = new SecretKeySpec(masterKey.take(CryptoConfig.AES_KEY_SIZE), "AES")

  // Session-level IV pool for concurrent resolution requests
  private val sessionIvPool = new ConcurrentHashMap[Long, Array[Byte]]()
  private val sessionCounter = new AtomicLong(System.nanoTime())

  private def acquireSessionIv(sessionId: Long): Array[Byte] = {
    val existing = sessionIvPool.get(sessionId)
    if (existing != null) {
      existing
    } else {
      val newIv = ivDerivation.deriveIv()
      val race = sessionIvPool.putIfAbsent(sessionId, newIv)
      if (race != null) race else newIv
    }
  }

  private def releaseSessionIv(sessionId: Long): Unit = {
    sessionIvPool.remove(sessionId)
  }

  private def encryptPayload(data: Array[Byte], iv: Array[Byte]): Array[Byte] = {
    val cipher = Cipher.getInstance(CryptoConfig.ALGORITHM)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, new IvParameterSpec(iv))
    cipher.doFinal(data)
  }

  private def decryptPayload(data: Array[Byte], iv: Array[Byte]): Array[Byte] = {
    val cipher = Cipher.getInstance(CryptoConfig.ALGORITHM)
    cipher.init(Cipher.DECRYPT_MODE, keySpec, new IvParameterSpec(iv))
    cipher.doFinal(data)
  }

  override def resolve(domain: String)(implicit ec: ExecutionContext): Future[Array[Byte]] = {
    Future {
      val entry = cache.get(domain)
      if (entry != null && (System.currentTimeMillis() - entry.timestamp) < entry.ttl) {
        decryptPayload(entry.encryptedResponse, entry.iv)
      } else {
        null
      }
    }
  }

  override def cacheResponse(domain: String, response: Array[Byte])(implicit ec: ExecutionContext): Future[Unit] = {
    Future {
      // Compute session for this caching operation
      val sessionId = computeSessionId(domain)
      val iv = acquireSessionIv(sessionId)

      try {
        val encrypted = encryptPayload(response, iv)
        val entry = new DnsCacheEntry(
          domain = domain,
          encryptedResponse = encrypted,
          iv = iv,
          ttl = 300000L,
          timestamp = System.currentTimeMillis()
        )
        cache.put(domain, entry)
      } finally {
        // Note: session IV released for reuse by other domains
        releaseSessionIv(sessionId)
      }
    }
  }

  // Session ID computation - maps domains to session slots
  // Uses hash-based bucketing to limit IV pool size
  private def computeSessionId(domain: String): Long = {
    // Bucket domains into session slots to bound memory
    val hash = domain.hashCode.toLong & 0x7FFFFFFFL
    hash % 64L  // 64 session slots
  }
}

object DnsResolverApp {
  def main(args: Array[String]): Unit = {
    implicit val ec: ExecutionContext = ExecutionContext.global
    val key = new Array[Byte](16)
    new SecureRandom().nextBytes(key)

    val resolver = new SecureDnsResolver(key)

    // Simulate concurrent DNS resolutions
    val domains = List("example.com", "test.org", "secure.net")
    val futures = domains.map { d =>
      val mockResponse = s"RESPONSE:$d:${System.nanoTime()}".getBytes("UTF-8")
      resolver.cacheResponse(d, mockResponse)
    }

    Future.sequence(futures).onComplete {
      case Success(_) => println("All DNS responses cached successfully")
      case Failure(e) => println(s"Error: ${e.getMessage}")
    }
  }
}
